import fs from 'node:fs/promises'
import path from 'node:path'

const distDir = path.resolve(process.argv[2] || 'dist')
const required = ['index.html', 'config/runtime.json']
const failures = []

for (const relative of required) {
  try {
    await fs.access(path.join(distDir, relative))
  } catch {
    failures.push(`필수 파일 없음: ${relative}`)
  }
}

async function walk(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const absolute = path.join(dir, entry.name)
    if (entry.isDirectory()) files.push(...(await walk(absolute)))
    else files.push(absolute)
  }
  return files
}

for (const file of await walk(distDir)) {
  if (/\.map$/i.test(file)) {
    failures.push(`source map 포함: ${path.relative(distDir, file)}`)
    continue
  }
  if (!/\.(?:html|css)$/i.test(file)) continue
  const text = await fs.readFile(file, 'utf8')
  const relative = path.relative(distDir, file)
  if (/(?:src|href)\s*=\s*["'](?:https?:)?\/\//i.test(text)) failures.push(`외부 asset URL: ${relative}`)
  if (/url\(\s*["']?https?:\/\//i.test(text)) failures.push(`외부 CSS URL: ${relative}`)
  if (/@import\s+(?:url\()?\s*["']?(?:https?:)?\/\//i.test(text)) failures.push(`외부 CSS import: ${relative}`)
}

const index = await fs.readFile(path.join(distDir, 'index.html'), 'utf8').catch(() => '')
if (/\b(?:src|href)=["']\//i.test(index)) failures.push('index.html에 root 절대 asset 경로가 있습니다.')

if (failures.length) {
  console.error(failures.join('\n'))
  process.exit(1)
}

console.log('[offline] OK: 외부 asset 참조 없음, 상대 경로 배포 가능')
import fs from 'node:fs'
import path from 'node:path'

const filePath = path.resolve(process.argv[2] || 'public/config/runtime.json')
const requiredStrings = ['appName', 'environment', 'backendBaseUrl', 'authSsoUrl']
const requiredBooleans = ['mockMode', 'enablePolicyWrites', 'enableMonitoring']
// 상대 경로가 실제로 same-origin인지 확인할 때 쓰는 sentinel origin.
const RELATIVE_BASE = 'https://relative.invalid/'
// 평문 http를 예외로 허용하는 개발용 loopback host.
const LOOPBACK_HOSTNAMES = ['localhost', '127.0.0.1', '[::1]']

function fail(message) {
  console.error(`[runtime-config] ${message}`)
  process.exit(1)
}

// allowedHosts 항목은 `host` 또는 `host:port`만 허용하고 비교 가능한 형태로 정규화한다.
function normalizeHostEntry(entry, protocol) {
  const trimmed = entry.trim()
  let parsed
  try {
    parsed = new URL(`${protocol}//${trimmed}`)
  } catch {
    fail(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  if (parsed.username || parsed.password || parsed.pathname !== '/' || parsed.search || parsed.hash || !parsed.hostname) {
    fail(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  return parsed.host
}

if (!fs.existsSync(filePath)) fail(`파일이 없습니다: ${filePath}`)

let config
try {
  config = JSON.parse(fs.readFileSync(filePath, 'utf8'))
} catch (error) {
  fail(`JSON 파싱 실패: ${error instanceof Error ? error.message : String(error)}`)
}

for (const key of requiredStrings) {
  if (typeof config[key] !== 'string' || !config[key].trim()) fail(`${key}는 비어 있지 않은 문자열이어야 합니다.`)
}

for (const key of requiredBooleans) {
  if (typeof config[key] !== 'boolean') fail(`${key}는 boolean이어야 합니다.`)
}

if (config.authLogoutUrl != null && typeof config.authLogoutUrl !== 'string') {
  fail('authLogoutUrl은 문자열이어야 합니다.')
}

if (!Number.isInteger(config.requestTimeoutMs) || config.requestTimeoutMs < 1000 || config.requestTimeoutMs > 120000) {
  fail('requestTimeoutMs는 1,000~120,000 사이의 정수여야 합니다.')
}

if (!Number.isInteger(config.pollIntervalMs) || config.pollIntervalMs < 5000 || config.pollIntervalMs > 300000) {
  fail('pollIntervalMs는 5,000~300,000 사이의 정수여야 합니다.')
}

if (!Array.isArray(config.allowedHosts) || config.allowedHosts.some((host) => typeof host !== 'string' || !host.trim())) {
  fail('allowedHosts는 문자열 배열이어야 합니다.')
}

// 잘못된 항목이 조용히 무시되지 않도록 절대 URL이 없어도 형식을 검사한다.
for (const host of config.allowedHosts) normalizeHostEntry(host, 'https:')

for (const key of ['backendBaseUrl', 'authSsoUrl', 'authLogoutUrl']) {
  const value = config[key]
  if (!value) continue
  if (/^https?:\/\//i.test(value)) {
    const url = new URL(value)
    if (url.username || url.password) fail(`${key} URL에는 자격증명을 포함할 수 없습니다.`)
    // access_token 헤더와 cookie를 평문으로 보내지 않도록 loopback 외에는 https만 허용한다.
    if (url.protocol === 'http:' && !LOOPBACK_HOSTNAMES.includes(url.hostname)) {
      fail(`${key}는 https를 사용해야 합니다. 평문 http는 loopback host에서만 허용됩니다.`)
    }
    // host가 아닌 hostname만 비교하면 allowlist된 host의 다른 port로 우회할 수 있다.
    const allowedEntries = config.allowedHosts.map((entry) => normalizeHostEntry(entry, url.protocol))
    if (!allowedEntries.includes(url.host)) {
      fail(`${key}의 host(${url.host})가 allowedHosts에 없습니다.`)
    }
  } else if (!value.startsWith('/') && !value.startsWith('./') && !value.startsWith('../')) {
    fail(`${key}는 상대 경로 또는 허용된 http(s) URL이어야 합니다.`)
  } else {
    // `//evil.test`나 `/\evil.test`는 `/`로 시작하지만 브라우저가 다른 origin으로 해석한다.
    let resolved
    try {
      resolved = new URL(value, RELATIVE_BASE)
    } catch {
      fail(`${key}를 URL로 해석할 수 없습니다.`)
    }
    if (resolved.origin !== new URL(RELATIVE_BASE).origin) {
      fail(`${key}는 다른 origin을 가리킬 수 없습니다.`)
    }
  }
}

